use std::{fs,path::Path,collections::BTreeMap,process::Command};
use serde_json::{Value,json};use sha2::{Digest,Sha256};
const R:&str="/tmp/zopro-poseidon-parallel";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn add(p:impl AsRef<Path>,pins:&mut BTreeMap<String,String>){let p=p.as_ref();pins.insert(p.display().to_string(),hash(p));}
fn main(){let r=Path::new(R);assert_eq!(read(r.join("native/result.json"))["status"],"complete");assert_eq!(read(r.join("native/core/tests.json"))["passed_tests"].as_array().unwrap().len(),116);
 let a=read(r.join("native/probe/artifacts.json"));let binary=a["binary"].as_str().unwrap();let mut pins:BTreeMap<String,String>=serde_json::from_value(read(r.join("source-pins.json"))).unwrap();for(p,h)in a["input_pins"].as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());add(p,&mut pins);}assert_eq!(hash(binary),a["binary_sha256"].as_str().unwrap());add(binary,&mut pins);
 for p in [r.join("prepare.rs"),r.join("prepare"),r.join("native-plan.json"),r.join("native/result.json"),r.join("native/probe/artifacts.json"),r.join("source-audit.json"),Path::new("/tmp/zopro-xtask-fast-screen-target/release/xtask").to_path_buf(),Path::new("/usr/bin/perf").to_path_buf()]{add(p,&mut pins);}
 let mut cases=Vec::new();let mut jobs=Vec::new();let mut steps=Vec::new();
 for groups in [1,4,16]{for workers in [16,32]{for c in [0,1]{for ragged in [0,1]{let name=format!("g{groups}-w{workers}-c{c}-h{ragged}");let case=json!({"name":name,"groups":groups,"workers":workers,"materialize_c":c==1,"ragged":ragged==1,"iterations":512/groups});let mask=format!("0-{}",workers-1);
 steps.push(json!({"kind":"command","name":name,"argv":["taskset","-c",mask,binary,groups.to_string(),c.to_string(),ragged.to_string(),workers.to_string(),"paired"],"timeout_seconds":600}));jobs.push(json!({"phase":"latency","name":name,"case":case}));cases.push(case);}}}}
 assert_eq!(cases.len(),24);
 for mode in ["control-a","control-b","plain","grouped"]{let p=r.join("profiles").join(mode);fs::create_dir_all(&p).unwrap();for file in ["ctl","ack"]{assert!(Command::new("mkfifo").arg(p.join(file)).status().unwrap().success());}let data=p.join("perf.data");let control=format!("--control=fifo:{},{}",p.join("ctl").display(),p.join("ack").display());let name=format!("profile-{mode}");
 steps.push(json!({"kind":"command","name":name,"argv":["sudo","-n","/usr/bin/perf","record","--no-buildid-cache","--clockid","mono","--delay=-1",control,"-e","cycles:u","-F","999","-o",data,"--","sudo","-n","-u","ubuntu","env",format!("ZOPRO_BENCH_PERF_CTL={}",p.join("ctl").display()),format!("ZOPRO_BENCH_PERF_ACK={}",p.join("ack").display()),"taskset","-c","0-31",binary,"16","0","1","32",mode],"timeout_seconds":600}));jobs.push(json!({"phase":"profile","name":name,"mode":mode,"workers":32,"groups":16,"materialize_c":false,"ragged":true,"iterations":4096}));}
 for mode in ["control-a","control-b","plain","grouped"]{let data=r.join("profiles").join(mode).join("perf.data");steps.push(json!({"kind":"command","name":format!("samples-{mode}"),"argv":["sudo","-n","/usr/bin/perf","script","--show-lost-events","-i",data,"-F","comm,pid,tid,time,event,ip,sym,period"],"timeout_seconds":180}));steps.push(json!({"kind":"command","name":format!("report-{mode}"),"argv":["sudo","-n","/usr/bin/perf","report","--stdio","--header","--percent-limit","0","-i",data],"timeout_seconds":180}));}
 save(r.join("cases.json"),&json!(cases));save(r.join("jobs.json"),&json!(jobs));add(r.join("cases.json"),&mut pins);add(r.join("jobs.json"),&mut pins);for(p,h)in &pins{assert_eq!(&hash(p),h);}save(r.join("measurement-pins.json"),&json!(pins));save(r.join("measurement-plan.json"),&json!({"version":1,"source_pins":r.join("measurement-pins.json"),"steps":steps}));println!("Frozen24pairedlatencyprocesses/672stages then4profiles;0SDK/Gnark;prior6946unchanged");
}
